// Warn in development if a human-type avatar renders an image with no accessible name.
//
// Scope is human-only: agent type ignores `src` entirely (no image renders), so there is
// nothing to describe. Warning there would demand alt text for an image that never exists.
// @see Requirements: 5.4 - human type + src SHALL require alt
// @see Requirements: 5 AC 5 - agent type SHALL ignore src
//
// `decorative` is the supported signal that an avatar is intentionally non-informative
// (it renders aria-hidden="true"), so it suppresses the warning — demanding alt text that
// aria-hidden will never announce is pointless work.
// @see Requirements: 9.2 - decorative=true applies aria-hidden="true"
//
// Edge semantics (Spec 126, O2): the check is `alt == null`, not `!alt`. Only
// setAttribute('alt', '') yields a genuinely empty alt; the `alt` setter treats '' as
// falsy and removes the attribute, so `avatar.alt = ''` collapses to absent and warns.
if (type === 'human' && src && alt == null && !decorative && typeof console !== 'undefined') {
  console.warn(
    'AvatarBaseElement: "alt" is required when "src" is provided. ' +
    'Add an alt description of the image; or, if this avatar is purely decorative ' +
    '(non-informative), set the "decorative" prop to hide it from screen readers.'
  );
}

